import { defineConfig } from '@zod-to-form/core';

import type * as Components from '@/components/zod-form';
import type * as ZodSchemas from './schema';

export default defineConfig<typeof Components, typeof ZodSchemas>({
  components: {
    source: '@/components/zod-form',
    overrides: {
      Checkbox: { controlled: true },
      Switch: { controlled: true },
      Select: { controlled: true },
      RadioGroup: { controlled: true },
      DatePicker: { controlled: true }
    }
  },
  defaults: {
    mode: 'submit',
    ui: 'shadcn',
    overwrite: false,
    serverAction: false,
    formProvider: false,
    // optimization: { level: 2 }  // 1 = decompose, 2 = native rules, 3 = cross-field
  },
  include: [],
  exclude: [],
  schemas: {
    schema: {}
  }
});

/**
 * Shared prop shape for controlled shadcn field adapters.
 *
 * z2f codegen binds controlled fields to all five RHF field props
 * (`value onChange onBlur ref name`). `ref` is supplied via React.forwardRef,
 * so it is NOT part of this props object — the remaining four (plus the
 * `disabled`/`id` UI props) are. Adapters must accept a SUPERSET of what
 * codegen emits, otherwise `tsc` fails in a real consumer project.
 */
export type ControlledFieldProps<V = unknown> = {
  value?: V;
  onChange?: (value: V) => void;
  onBlur?: () => void;
  name?: string;
  disabled?: boolean;
  id?: string;
};

import * as React from 'react';
import { Input as ShadcnInput } from '@/components/ui/input';

export const Input = React.forwardRef<HTMLInputElement, React.ComponentProps<typeof ShadcnInput>>(
  (props, ref) => <ShadcnInput ref={ref} {...props} />
);
Input.displayName = 'Input';

import * as React from 'react';
import { Textarea as ShadcnTextarea } from '@/components/ui/textarea';

export const Textarea = React.forwardRef<
  HTMLTextAreaElement,
  React.ComponentProps<typeof ShadcnTextarea>
>((props, ref) => <ShadcnTextarea ref={ref} {...props} />);
Textarea.displayName = 'Textarea';

import * as React from 'react';
import { Checkbox as ShadcnCheckbox } from '@/components/ui/checkbox';
import type { ControlledFieldProps } from './types';

export const Checkbox = React.forwardRef<HTMLButtonElement, ControlledFieldProps<boolean>>(
  ({ value, onChange, onBlur, name, disabled, id }, ref) => (
    <ShadcnCheckbox
      ref={ref}
      id={id}
      name={name}
      disabled={disabled}
      onBlur={onBlur}
      checked={!!value}
      onCheckedChange={(c) => onChange?.(c === true)}
    />
  )
);
Checkbox.displayName = 'Checkbox';

import * as React from 'react';
import { Switch as ShadcnSwitch } from '@/components/ui/switch';
import type { ControlledFieldProps } from './types';

export const Switch = React.forwardRef<HTMLButtonElement, ControlledFieldProps<boolean>>(
  ({ value, onChange, onBlur, name, disabled, id }, ref) => (
    <ShadcnSwitch
      ref={ref}
      id={id}
      name={name}
      disabled={disabled}
      onBlur={onBlur}
      checked={!!value}
      onCheckedChange={(c) => onChange?.(c === true)}
    />
  )
);
Switch.displayName = 'Switch';

import * as React from 'react';
import {
  Select as ShadcnSelect,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem
} from '@/components/ui/select';
import type { FormFieldOption } from '@zod-to-form/core';
import type { ControlledFieldProps } from './types';

type Props = ControlledFieldProps<string | number> & {
  placeholder?: string;
  options?: FormFieldOption[];
};

export const Select = React.forwardRef<HTMLButtonElement, Props>(
  ({ value, onChange, onBlur, name, disabled, id, placeholder, options = [] }, ref) => (
    <ShadcnSelect
      value={value == null ? undefined : String(value)}
      onValueChange={(v) => onChange?.(v)}
      disabled={disabled}
    >
      <SelectTrigger ref={ref} id={id} name={name} onBlur={onBlur}>
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        {options.map((o) => (
          <SelectItem key={String(o.value)} value={String(o.value)} disabled={o.disabled}>
            {o.label}
          </SelectItem>
        ))}
      </SelectContent>
    </ShadcnSelect>
  )
);
Select.displayName = 'Select';

import * as React from 'react';
import { RadioGroup as ShadcnRadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Label } from '@/components/ui/label';
import type { FormFieldOption } from '@zod-to-form/core';
import type { ControlledFieldProps } from './types';

type Props = ControlledFieldProps<string | number> & {
  options?: FormFieldOption[];
};

export const RadioGroup = React.forwardRef<HTMLDivElement, Props>(
  ({ value, onChange, onBlur, name, disabled, options = [] }, ref) => (
    <ShadcnRadioGroup
      ref={ref}
      name={name}
      onBlur={onBlur}
      value={value == null ? undefined : String(value)}
      onValueChange={(v) => onChange?.(v)}
      disabled={disabled}
    >
      {options.map((o) => {
        const itemId = `${name ?? 'radio'}-${String(o.value)}`;
        return (
          <div key={String(o.value)}>
            <RadioGroupItem value={String(o.value)} id={itemId} disabled={o.disabled} />
            <Label htmlFor={itemId}>{o.label}</Label>
          </div>
        );
      })}
    </ShadcnRadioGroup>
  )
);
RadioGroup.displayName = 'RadioGroup';

import * as React from 'react';
import { format } from 'date-fns';
import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverTrigger, PopoverContent } from '@/components/ui/popover';
import type { ControlledFieldProps } from './types';

export const DatePicker = React.forwardRef<
  HTMLButtonElement,
  ControlledFieldProps<Date | string | undefined>
>(({ value, onChange, onBlur, name, disabled, id }, ref) => {
  const date =
    value == null || value === '' ? undefined : value instanceof Date ? value : new Date(value);

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          ref={ref}
          id={id}
          name={name}
          onBlur={onBlur}
          type="button"
          variant="outline"
          disabled={disabled}
        >
          {date ? format(date, 'PPP') : 'Pick a date'}
        </Button>
      </PopoverTrigger>
      <PopoverContent>
        <Calendar mode="single" selected={date} onSelect={(d?: Date) => onChange?.(d)} />
      </PopoverContent>
    </Popover>
  );
});
DatePicker.displayName = 'DatePicker';

/**
 * Aggregated exports for all shadcn field adapter components.
 * Provides both named re-exports and a keyed `components` map for
 * the @zod-to-form/react runtime component registry.
 */
export { Input } from './input';
export { Textarea } from './textarea';
export { Checkbox } from './checkbox';
export { Switch } from './switch';
export { Select } from './select';
export { RadioGroup } from './radio-group';
export { DatePicker } from './date-picker';

// Re-export the shadcn Form* layout primitives so codegen/?z2f-generated forms
// can import BOTH the field adapters AND the field-template wrappers from the
// single `@/components/zod-form` module. These are template wrappers, NOT field
// components — they are deliberately absent from the `components` map below.
export {
  FormItem,
  FormControl,
  FormLabel,
  FormMessage,
  FormDescription,
  FormField
} from '@/components/ui/form';

import { Input } from './input';
import { Textarea } from './textarea';
import { Checkbox } from './checkbox';
import { Switch } from './switch';
import { Select } from './select';
import { RadioGroup } from './radio-group';
import { DatePicker } from './date-picker';

export const components = {
  Input,
  Textarea,
  Checkbox,
  Switch,
  Select,
  RadioGroup,
  DatePicker
};

import { ZodForm } from '@zod-to-form/react';
import { schema } from '@/lib/zod-form/schema';
import { components } from '@/components/zod-form';

export function ExampleForm() {
  return (
    <ZodForm
      schema={schema}
      components={components}
      onSubmit={(_data) => {
        // handle submission
      }}
    />
  );
}
